    "easy",
    "\u6808/\u961f\u5217",
    "\u7ed9\u5b9a\u4e00\u4e2a\u6574\u6570\u6570\u636e\u6d41\u548c\u4e00\u4e2a\u7a97\u53e3\u5927\u5c0f\uff0c\u6839\u636e\u8be5\u6ed1\u52a8\u7a97\u53e3\u7684\u5927\u5c0f\uff0c\u8ba1\u7b97\u6ed1\u52a8\u7a97\u53e3\u91cc\u6240\u6709\u6570\u5b57\u7684\u5e73\u5747\u503c\u3002\n\n\u5b9e\u73b0 MovingAverage \u7c7b\uff1a\n\n\tMovingAverage(int size) \u7528\u7a97\u53e3\u5927\u5c0f size \u521d\u59cb\u5316\u5bf9\u8c61\u3002\n\n\tdouble next(int val)\u00a0\u6210\u5458\u51fd\u6570 next\u00a0\u6bcf\u6b21\u8c03\u7528\u7684\u65f6\u5019\u90fd\u4f1a\u5f80\u6ed1\u52a8\u7a97\u53e3\u589e\u52a0\u4e00\u4e2a\u6574\u6570\uff0c\u8bf7\u8ba1\u7b97\u5e76\u8fd4\u56de\u6570\u636e\u6d41\u4e2d\u6700\u540e size \u4e2a\u503c\u7684\u79fb\u52a8\u5e73\u5747\u503c\uff0c\u5373\u6ed1\u52a8\u7a97\u53e3\u91cc\u6240\u6709\u6570\u5b57\u7684\u5e73\u5747\u503c\u3002\n\n\u00a0\n\n\u793a\u4f8b\uff1a\n\n```\n\u8f93\u5165\uff1a\ninputs = [\"MovingAverage\", \"next\", \"next\", \"next\", \"next\"]\ninputs = [[3], [1], [10], [3], [5]]\n\u8f93\u51fa\uff1a\n[null, 1.0, 5.5, 4.66667, 6.0]\n\n\u89e3\u91ca\uff1a\nMovingAverage movingAverage = new MovingAverage(3);\nmovingAverage.next(1); // \u8fd4\u56de 1.0 = 1 / 1\nmovingAverage.next(10); // \u8fd4\u56de 5.5 = (1 + 10) / 2\nmovingAverage.next(3); // \u8fd4\u56de 4.66667 = (1 + 10 + 3) / 3\nmovingAverage.next(5); // \u8fd4\u56de 6.0 = (10 + 3 + 5) / 3\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= size <= 1000\n\n\t-105 <= val <= 105\n\n\t\u6700\u591a\u8c03\u7528 next \u65b9\u6cd5 104 \u6b21\n\n\u00a0\n\n\u6ce8\u610f\uff1a\u672c\u9898\u4e0e\u4e3b\u7ad9 346\u00a0\u9898\u76f8\u540c\uff1a\u00a0https://leetcode.cn/problems/moving-average-from-data-stream/",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1ainputs\u3001inputs\u3002",
    "\u8f93\u51fa list<String> \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\nclass MovingAverage:\n    def __init__(self, size: int):\n        self.size = size\n        self.sum = 0\n        self.q = deque()\n\n    def next(self, val: int) -> float:\n        if len(self.q) == self.size:\n            self.sum -= self.q.popleft()\n        self.sum += val\n        self.q.append(val)\n        return self.sum / len(self.q)\n\ndef main():\n    _lines = [x for x in sys.stdin.read().split('\\n') if x.strip() != '']\n    _ops = json.loads(_lines[0])\n    _args = json.loads(_lines[1]) if len(_lines) > 1 else []\n    _obj = None\n    _out = []\n    for _i, _op in enumerate(_ops):\n        _a = _args[_i] if _i < len(_args) else []\n        if _i == 0:\n            _obj = MovingAverage(*_a)\n            _out.append(None)\n        else:\n            _out.append(getattr(_obj, _op)(*_a))\n    print(json.dumps(_out, separators=(',', ':')))\n\nmain()\n",
