    "\u7ed9\u4f60\u4e00\u4e2a\u6570\u7ec4\u00a0prices\u00a0\uff0c\u5176\u4e2d\u00a0prices[i]\u00a0\u662f\u5546\u5e97\u91cc\u7b2c\u00a0i\u00a0\u4ef6\u5546\u54c1\u7684\u4ef7\u683c\u3002\n\n\u5546\u5e97\u91cc\u6b63\u5728\u8fdb\u884c\u4fc3\u9500\u6d3b\u52a8\uff0c\u5982\u679c\u4f60\u8981\u4e70\u7b2c\u00a0i\u00a0\u4ef6\u5546\u54c1\uff0c\u90a3\u4e48\u4f60\u53ef\u4ee5\u5f97\u5230\u4e0e prices[j] \u76f8\u7b49\u7684\u6298\u6263\uff0c\u5176\u4e2d\u00a0j\u00a0\u662f\u6ee1\u8db3\u00a0j > i\u00a0\u4e14\u00a0prices[j] <= prices[i]\u00a0\u7684\u00a0\u6700\u5c0f\u4e0b\u6807\u00a0\uff0c\u5982\u679c\u6ca1\u6709\u6ee1\u8db3\u6761\u4ef6\u7684\u00a0j\u00a0\uff0c\u4f60\u5c06\u6ca1\u6709\u4efb\u4f55\u6298\u6263\u3002\n\n\u8bf7\u4f60\u8fd4\u56de\u4e00\u4e2a\u6570\u7ec4\uff0c\u6570\u7ec4\u4e2d\u7b2c\u00a0i\u00a0\u4e2a\u5143\u7d20\u662f\u6298\u6263\u540e\u4f60\u8d2d\u4e70\u5546\u54c1 i\u00a0\u6700\u7ec8\u9700\u8981\u652f\u4ed8\u7684\u4ef7\u683c\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1aprices = [8,4,6,2,3]\n\u8f93\u51fa\uff1a[4,2,4,2,3]\n\u89e3\u91ca\uff1a\n\u5546\u54c1 0 \u7684\u4ef7\u683c\u4e3a price[0]=8 \uff0c\u4f60\u5c06\u5f97\u5230 prices[1]=4 \u7684\u6298\u6263\uff0c\u6240\u4ee5\u6700\u7ec8\u4ef7\u683c\u4e3a 8 - 4 = 4 \u3002\n\u5546\u54c1 1 \u7684\u4ef7\u683c\u4e3a price[1]=4 \uff0c\u4f60\u5c06\u5f97\u5230 prices[3]=2 \u7684\u6298\u6263\uff0c\u6240\u4ee5\u6700\u7ec8\u4ef7\u683c\u4e3a 4 - 2 = 2 \u3002\n\u5546\u54c1 2 \u7684\u4ef7\u683c\u4e3a price[2]=6 \uff0c\u4f60\u5c06\u5f97\u5230 prices[3]=2 \u7684\u6298\u6263\uff0c\u6240\u4ee5\u6700\u7ec8\u4ef7\u683c\u4e3a 6 - 2 = 4 \u3002\n\u5546\u54c1 3 \u548c 4 \u90fd\u6ca1\u6709\u6298\u6263\u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1aprices = [1,2,3,4,5]\n\u8f93\u51fa\uff1a[1,2,3,4,5]\n\u89e3\u91ca\uff1a\u5728\u8fd9\u4e2a\u4f8b\u5b50\u4e2d\uff0c\u6240\u6709\u5546\u54c1\u90fd\u6ca1\u6709\u6298\u6263\u3002\n```\n\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165\uff1aprices = [10,1,1,6]\n\u8f93\u51fa\uff1a[9,0,1,6]\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= prices.length <= 500\n\n\t1 <= prices[i] <= 10^3",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1aprices\u3002",
    "\u8f93\u51fa integer[] \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def finalPrices(self, prices: List[int]) -> List[int]:\n        n = len(prices)\n        ans = [0] * n\n        for i, p in enumerate(prices):\n            discount = 0\n            for j in range(i + 1, n):\n                if prices[j] <= p:\n                    discount = prices[j]\n                    break\n            ans[i] = p - discount\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.finalPrices(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
